#!/usr/bin/env bun
/**
 * make-lifecycle — generate a new lifecycle, from steps or from agents.
 *
 * Usage:
 *     bun <pi-crust>/scripts/make-lifecycle.ts --name ship --steps plan,build,verify
 *     bun <pi-crust>/scripts/make-lifecycle.ts --name review-docs --agents scout,builder
 *
 * `--steps` is the one to reach for: the generated file is four lines over the
 * step registry, and it inherits roster validation, the request phase, and
 * `--resume` without declaring any of them. `--agents` is the escape hatch for
 * a chain the ten steps do not cover.
 *
 * Each named agent becomes one agent phase, chained by envelope. Starter agents
 * map to their concrete output types; any other agent in the roster gets
 * `genericOutput` (define a concrete one in .pi-crust/modules/typedefs/envelope.ts
 * and swap it in).
 *
 * Agent names are checked against the roster before anything is written. The
 * Python generator this replaces did not, so a typo produced a file that looked
 * right and failed at startup on the first run.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

const OUTPUT_TYPES: Readonly<Record<string, string>> = {
  planner: 'planOutput',
  builder: 'buildOutput',
  scout: 'scoutOutput',
  tester: 'buildOutput',
  reviewer: 'reviewOutput',
  'code-reviewer': 'reviewOutput',
  documenter: 'documentOutput',
}

const CONFIG_PATH = join('.pi-crust', 'config', 'crust.config.yaml')

/** Mirrors STEP_NAMES in .pi-crust/modules/typedefs/step.ts — the generator runs
 * from the skill, which cannot import out of a repository it has not stamped
 * yet. Keep the two in step. */
const STEP_NAMES: readonly string[] = [
  'prompt',
  'scout',
  'identify',
  'diagnose',
  'conceptualize',
  'plan',
  'design',
  'poc',
  'test',
  'build',
  'verify',
  'review',
  'code-review',
  'revise',
  'commit',
  'document',
]

const say = (line: string): void => {
  process.stdout.write(`${line}\n`)
}

const flagValue = (name: string): string | undefined => {
  const argv = process.argv.slice(2)
  const index = argv.indexOf(`--${name}`)
  if (index !== -1) {
    return argv[index + 1]
  }
  const inline = argv.find((token) => token.startsWith(`--${name}=`))
  return inline?.slice(`--${name}=`.length)
}

const titleOf = (name: string): string =>
  name
    .split(/[-_]/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')

const rosterNames = (): readonly string[] => {
  const raw = Bun.YAML.parse(readFileSync(CONFIG_PATH, 'utf8')) as {
    agents?: ReadonlyArray<{ name?: unknown }>
  }
  return (raw.agents ?? []).flatMap((agent) =>
    typeof agent.name === 'string' ? [agent.name] : [],
  )
}

const phaseBlock = (
  phaseName: string,
  agent: string,
  outputType: string,
): string =>
  `  // TODO: replace this description — say what THIS phase does and why.
  previous = await phase(
    phaseParams({
      name: '${phaseName}',
      kind: 'agent',
      owner: '${agent}',
      description: 'Run ${agent} over the request and hand its envelope on',
    }),
    (ph) =>
      callAgent(run, ph, {
        outputType: ${outputType},
        prompt,
        ...(previous === undefined ? {} : { previous }),
        gates: [artifactsExist],
      }),
    replayAgent(run, '${agent}', ${outputType}),
  )
`

const template = (
  params: Readonly<{
    name: string
    chain: string
    imports: string
    agents: string
    phases: string
  }>,
): string => `#!/usr/bin/env bun
/**
 * pi-crust ${titleOf(params.name)} — generated by make-lifecycle.
 *
 * Usage:
 *     bun .pi-crust/lifecycles/${params.name}.ts "<prompt or path/to/prompt.md>" [--config .pi-crust/config/crust.config.yaml] [--run-id a1b2c3d4]
 *
 * Phases: engineer(request) -> ${params.chain}
 */

import type { TEnvelopeBase } from '../modules/typedefs/envelope'
import { ${params.imports} } from '../modules/typedefs/envelope'
import { phaseParams } from '../modules/typedefs/phase'
import { callAgent } from '../modules/use-cases/execute-agent'
import { artifactsExist } from '../modules/use-cases/gates'
import { loadConfig } from '../modules/use-cases/load-config'
import type { TWorkflowArgs } from '../modules/use-cases/parse-cli'
import { runCli, workflowArgs } from '../modules/use-cases/parse-cli'
import { replayAgent, replayNothing } from '../modules/use-cases/replay'
import { resolvePrompt } from '../modules/use-cases/resolve-prompt'
import { resumablePhase } from '../modules/use-cases/resume'
import { finish } from '../modules/use-cases/run-phase'
import { startSession } from '../modules/use-cases/start-session'
import { validateAgents } from '../modules/use-cases/validate-agents'

export const REQUIRED_AGENTS = ${params.agents}

export const main = async (args: TWorkflowArgs): Promise<number> => {
  const { prompt } = args
  const cfg = loadConfig(args.config)
  validateAgents(cfg, REQUIRED_AGENTS)
  const run = startSession(cfg, args.runId, { resume: args.resume })
  const phase = resumablePhase(run)

  await phase(
    phaseParams({
      name: 'request',
      kind: 'engineer',
      owner: run.engineer,
      description: 'Capture the incoming ask',
    }),
    (ph) => ph.log({ input: prompt }),
    replayNothing,
  )

  let previous: TEnvelopeBase | undefined

${params.phases}
  return finish(run, { accepted: true })
}

if (import.meta.main) {
  await runCli('.pi-crust/lifecycles/${params.name}.ts', (args) =>
    main(workflowArgs(args, resolvePrompt(args.prompt))),
  )
}
`

const stepsTemplate = (name: string, steps: readonly string[]): string =>
  `#!/usr/bin/env bun
/**
 * pi-crust ${titleOf(name)} — generated by make-lifecycle.
 *
 * Usage:
 *     bun .pi-crust/lifecycles/${name}.ts "<prompt or path/to/prompt.md>" [--config .pi-crust/config/crust.config.yaml] [--run-id a1b2c3d4] [--resume]
 *
 * Phases: engineer(request) -> ${steps.join(' -> ')}
 *
 * TODO: replace this paragraph — say what this chain is FOR and when to reach
 * for it rather than one of the others.
 */

import type { TWorkflowArgs } from '../modules/use-cases/parse-cli'
import { runCli, workflowArgs } from '../modules/use-cases/parse-cli'
import { resolvePrompt } from '../modules/use-cases/resolve-prompt'
import { runWorkflow } from '../modules/use-cases/run-workflow'

export const STEPS = ${JSON.stringify(steps)} as const

export const main = (args: TWorkflowArgs): Promise<number> =>
  runWorkflow(args, STEPS)

if (import.meta.main) {
  await runCli('.pi-crust/lifecycles/${name}.ts', (args) =>
    main(workflowArgs(args, resolvePrompt(args.prompt))),
  )
}
`

const writeFile = (name: string, body: string, force: boolean): number => {
  const destination = join(process.cwd(), '.pi-crust', 'lifecycles', `${name}.ts`)
  if (existsSync(destination) && !force) {
    say(`${destination} already exists — use --force to overwrite`)
    return 1
  }
  mkdirSync(dirname(destination), { recursive: true })
  writeFileSync(destination, body, 'utf8')
  say(`wrote ${destination}`)
  return 0
}

const main = (): number => {
  const name = flagValue('name')
  const agentsArg = flagValue('agents')
  const stepsArg = flagValue('steps')
  const force = process.argv.includes('--force')

  if (name === undefined || (agentsArg === undefined && stepsArg === undefined)) {
    say(
      'usage: bun <pi-crust>/scripts/make-lifecycle.ts --name <kebab-name> ' +
        '(--steps plan,build,verify | --agents scout,builder) [--force]',
    )
    return 2
  }

  if (stepsArg !== undefined) {
    const steps = stepsArg.split(',').map((step) => step.trim()).filter(Boolean)
    const unknown = steps.filter((step) => !STEP_NAMES.includes(step))
    if (unknown.length > 0) {
      say(
        `not a step: ${unknown.join(', ')} — valid steps are ${STEP_NAMES.join(', ')}`,
      )
      return 1
    }
    const code = writeFile(name, stepsTemplate(name, steps), force)
    if (code === 0) {
      say('next: replace the TODO paragraph — say what the chain is for')
      say(`run: bun .pi-crust/lifecycles/${name}.ts "your request"`)
    }
    return code
  }
  if (agentsArg === undefined) {
    return 2
  }

  const agentNames = agentsArg
    .split(',')
    .map((agent) => agent.trim())
    .filter(Boolean)
  if (agentNames.length === 0) {
    say('no agents given')
    return 1
  }

  if (!existsSync(CONFIG_PATH)) {
    say(
      `${CONFIG_PATH} does not exist — run the install, or ` +
        'bun <pi-crust>/scripts/make-config.ts, before generating a workflow',
    )
    return 1
  }
  const roster = rosterNames()
  const unknown = agentNames.filter((agent) => !roster.includes(agent))
  if (unknown.length > 0) {
    say(
      `not in the roster: ${unknown.join(', ')} — available: ${roster.join(', ')}. ` +
        'Add the agent to the config and its prompt pair first (see cookbooks/update_config.md).',
    )
    return 1
  }

  const types = agentNames.map(
    (agent) => OUTPUT_TYPES[agent] ?? 'genericOutput',
  )
  const seen = new Map<string, number>()
  const phases = agentNames.map((agent, index) => {
    const count = (seen.get(agent) ?? 0) + 1
    seen.set(agent, count)
    const phaseName = count === 1 ? agent : `${agent}_${count}`
    return phaseBlock(phaseName, agent, types[index] ?? 'genericOutput')
  })

  const code = writeFile(
    name,
    template({
      name,
      chain: agentNames.join(' -> '),
      imports: [...new Set(types)].toSorted().join(', '),
      agents: JSON.stringify([...new Set(agentNames)].toSorted()),
      phases: phases.join('\n'),
    }),
    force,
  )
  if (code !== 0) {
    return code
  }
  say(
    'next: replace each phase description — a generated one says nothing, and ' +
      'the description is the only intent the trace ever shows',
  )
  say(`run: bun .pi-crust/lifecycles/${name}.ts "your request"`)
  return 0
}

if (import.meta.main) {
  process.exit(main())
}
